// Build the job envelope for NWS alerts ingestion
// Source ID for National Weather Service alerts
const source_id = 'src_weather-gov-alerts';

// Deterministic idempotency key using execution ID and timestamp
const idempotency_key = `n8n-${$execution.id}-${Date.now()}`;

// Return the job envelope
return [{ 
  json: { 
    source_id: source_id, 
    idempotency_key: idempotency_key,
    product: 'ops',
    tenant_id: 'shared',
    workspace_id: 'shared',
    captured_at: new Date().toISOString(),
    source_url: 'https://api.weather.gov/alerts/active',
    source_type: 'weather_gov_alerts',
    provenance: {
      source: 'U.S. National Weather Service',
      method: 'api',
      license: 'public_domain',
      retrieved_at: new Date().toISOString()
    }
  } 
}];

// Extract and normalize NWS alert features
const features = $json.features || [];

// Map features to normalized records
const normalizedRecords = features.map(feature => {
  const properties = feature.properties || {};
  const geometry = feature.geometry || {};

  return {
    json: {
      id: properties.id || feature.id || '',
      title: properties.headline || properties.event || '',
      summary: properties.description || '',
      event_type: properties.event || '',
      severity: properties.severity || '',
      area: properties.area || '',
      sender: properties.sender || '',
      sent: properties.sent || '',
      effective: properties.effective || '',
      onset: properties.onset || '',
      expires: properties.expires || '',
      ends: properties.ends || '',
      status: properties.status || '',
      message_type: properties.messageType || '',
      category: properties.category || '',
      response: properties.response || '',
      urgency: properties.urgency || '',
      certainty: properties.certainty || '',
      parameters: properties.parameters || {},
      geometry_type: geometry.type || '',
      coordinates: geometry.coordinates || [],
      raw_feature: feature,
      source_id: 'src_weather-gov-alerts',
      ingested_at: new Date().toISOString(),
      provenance: {
        source: 'U.S. National Weather Service API',
        url: 'https://api.weather.gov/alerts/active',
        retrieved_at: new Date().toISOString(),
        license: 'public_domain'
      }
    }
  };
});

return normalizedRecords;

// Deduplicate alerts by ID
const seenIds = new Set();
const uniqueRecords = [];

for (const record of $input.all()) {
  const id = record.json.id;
  if (id && !seenIds.has(id)) {
    seenIds.add(id);
    uniqueRecords.push(record);
  } else if (!id) {
    // Log records without IDs for debugging
    $execution.resume(
      'Missing ID detected',
      { severity: 'warning', record: record.json }
    );
  }
}

return uniqueRecords;

// Error handling and logging
if ($execution.error) {
  $execution.resume('NWS alerts ingestion failed', {
    error: $execution.error,
    source: 'src_weather-gov-alerts',
    timestamp: new Date().toISOString()
  });
}

// Log success metrics
const recordCount = $input.all().length;
$execution.resume('NWS alerts ingestion completed', {
  records_processed: recordCount,
  source: 'src_weather-gov-alerts',
  timestamp: new Date().toISOString()
});
